-- ═══ 3. CHECK constraints ════════════════════════════════════════════════════

-- Catalogue
ALTER TABLE "category" ADD CONSTRAINT "category_not_own_parent_check"
  CHECK ("parent_id" IS NULL OR "parent_id" <> "id");
ALTER TABLE "collection" ADD CONSTRAINT "collection_schedule_check"
  CHECK ("starts_at" IS NULL OR "ends_at" IS NULL OR "ends_at" > "starts_at");
ALTER TABLE "product" ADD CONSTRAINT "product_short_description_length_check"
  CHECK (char_length("short_description") <= 200);
ALTER TABLE "product" ADD CONSTRAINT "product_published_at_check"
  CHECK ("status" <> 'PUBLISHED' OR "published_at" IS NOT NULL);
ALTER TABLE "colour" ADD CONSTRAINT "colour_swatch_hex_check"
  CHECK ("swatch_hex" ~ '^#[0-9A-Fa-f]{6}$');
ALTER TABLE "product_variant" ADD CONSTRAINT "product_variant_price_check"
  CHECK ("price_paise" > 0);
ALTER TABLE "product_variant" ADD CONSTRAINT "product_variant_compare_at_price_check"
  CHECK ("compare_at_price_paise" IS NULL OR "compare_at_price_paise" > "price_paise");
ALTER TABLE "product_image" ADD CONSTRAINT "product_image_alt_check"
  CHECK (btrim("alt") <> '');
ALTER TABLE "media_asset" ADD CONSTRAINT "media_asset_dimensions_check"
  CHECK ("width" > 0 AND "height" > 0 AND "bytes" > 0);

-- Inventory: never negative, never more reserved than on hand (D-105)
ALTER TABLE "inventory_level" ADD CONSTRAINT "inventory_level_on_hand_check"
  CHECK ("on_hand" >= 0);
ALTER TABLE "inventory_level" ADD CONSTRAINT "inventory_level_reserved_check"
  CHECK ("reserved" >= 0 AND "reserved" <= "on_hand");
ALTER TABLE "inventory_level" ADD CONSTRAINT "inventory_level_low_stock_threshold_check"
  CHECK ("low_stock_threshold" >= 0);
ALTER TABLE "inventory_level" ADD CONSTRAINT "inventory_level_version_check"
  CHECK ("version" >= 0);
ALTER TABLE "stock_movement" ADD CONSTRAINT "stock_movement_reason_check"
  CHECK ("type" NOT IN ('ADJUSTMENT', 'CORRECTION') OR btrim(coalesce("reason", '')) <> '');
ALTER TABLE "stock_movement" ADD CONSTRAINT "stock_movement_delta_check"
  CHECK ("on_hand_delta" <> 0 OR "reserved_delta" <> 0);
ALTER TABLE "stock_movement" ADD CONSTRAINT "stock_movement_reference_check"
  CHECK (("reference_type" IS NULL) = ("reference_id" IS NULL));
ALTER TABLE "stock_reservation" ADD CONSTRAINT "stock_reservation_quantity_check"
  CHECK ("quantity" > 0);
-- An active reservation must expire, and after it was created.
ALTER TABLE "stock_reservation" ADD CONSTRAINT "stock_reservation_expiry_check"
  CHECK ("status" <> 'ACTIVE' OR ("expires_at" IS NOT NULL AND "expires_at" > "created_at"));

-- Admin and security
ALTER TABLE "admin_user" ADD CONSTRAINT "admin_user_failed_login_count_check"
  CHECK ("failed_login_count" >= 0);
-- SHA-256 digest of the session token; the token itself is never stored.
ALTER TABLE "admin_session" ADD CONSTRAINT "admin_session_token_hash_check"
  CHECK (octet_length("token_hash") = 32);
ALTER TABLE "admin_session" ADD CONSTRAINT "admin_session_expiry_check"
  CHECK ("expires_at" > "created_at");

-- Content
ALTER TABLE "content_block" ADD CONSTRAINT "content_block_published_check"
  CHECK (("published" IS NULL) = ("published_at" IS NULL));
-- Pages that require verification cannot be published until verified (D-010).
ALTER TABLE "page" ADD CONSTRAINT "page_verification_required_check"
  CHECK (NOT "requires_verification" OR "status" <> 'PUBLISHED' OR "verified_at" IS NOT NULL);
ALTER TABLE "page" ADD CONSTRAINT "page_verified_by_check"
  CHECK (("verified_at" IS NULL) = ("verified_by_admin_id" IS NULL));
-- The Rehma Foundation page can never opt out of verification.
ALTER TABLE "page" ADD CONSTRAINT "page_rehma_requires_verification_check"
  CHECK ("slug" <> 'rehma-foundation' OR "requires_verification");
ALTER TABLE "navigation_item" ADD CONSTRAINT "navigation_item_target_check"
  CHECK (
    ("target_type" = 'URL' AND "url" IS NOT NULL AND "target_id" IS NULL)
    OR ("target_type" <> 'URL' AND "target_id" IS NOT NULL AND "url" IS NULL)
  );

-- ═══ 4. Append-only triggers (D-057) ═════════════════════════════════════════
-- Default SQLSTATE P0001: other codes (e.g. 23001) make Prisma report a
-- misleading foreign-key error (phase-6-plan.md).
CREATE FUNCTION "reject_append_only_change"() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END;
$$;

CREATE TRIGGER "stock_movement_append_only"
  BEFORE UPDATE OR DELETE ON "stock_movement"
  FOR EACH ROW EXECUTE FUNCTION "reject_append_only_change"();
CREATE TRIGGER "stock_movement_no_truncate"
  BEFORE TRUNCATE ON "stock_movement"
  FOR EACH STATEMENT EXECUTE FUNCTION "reject_append_only_change"();

CREATE TRIGGER "audit_log_append_only"
  BEFORE UPDATE OR DELETE ON "audit_log"
  FOR EACH ROW EXECUTE FUNCTION "reject_append_only_change"();
CREATE TRIGGER "audit_log_no_truncate"
  BEFORE TRUNCATE ON "audit_log"
  FOR EACH STATEMENT EXECUTE FUNCTION "reject_append_only_change"();

